            $fundBalance=(float)($fundRow['balance']??0);
            if($ledgerTab==='students'||$ledgerTab==='offset')foreach(cmhome_rows($db,"SELECT l.student_id,COALESCE(SUM(l.amount),0) AS amount FROM cmhome_ledger l LEFT JOIN cmhome_ledger_done d ON d.class_id=l.class_id AND d.school_year=l.school_year AND d.ledger_id=l.id WHERE l.class_id=? AND l.school_year=? AND l.entry_date BETWEEN ? AND ? AND l.kind='thu' AND l.student_id<>'' AND d.ledger_id IS NULL GROUP BY l.student_id",[$classId,$year,$month.'-01',date('Y-m-t',strtotime($month.'-01'))]) as $due)$studentDue[(string)$due['student_id']]=(float)$due['amount'];
            $ledgerSummary=cmhome_rows($db,"SELECT student_id,COUNT(*) AS entries,COALESCE(SUM(CASE WHEN kind='thu' THEN amount ELSE 0 END),0) AS income,COALESCE(SUM(CASE WHEN kind='chi' THEN amount ELSE 0 END),0) AS expense FROM cmhome_ledger WHERE class_id=? AND school_year=? AND entry_date BETWEEN ? AND ? GROUP BY student_id",[$classId,$year,$month.'-01',date('Y-m-t',strtotime($month.'-01'))]);
            $ledgerTotals=['income'=>0,'expense'=>0];$summaryById=[];
            foreach($ledgerSummary as $entry){$ledgerTotals['income']+=(float)$entry['income'];$ledgerTotals['expense']+=(float)$entry['expense'];$summaryById[(string)$entry['student_id']]=true;}
            if($ledgerTab==='students')foreach($students as $student){$sid=(string)$student['id'];if(!isset($summaryById[$sid]))$ledgerSummary[]=['student_id'=>$sid,'entries'=>0,'income'=>0,'expense'=>0];}
            usort($ledgerSummary,static function($a,$b)use($studentMap){$nameA=$a['student_id']===''?'':($studentMap[$a['student_id']]['name']??$a['student_id']);$nameB=$b['student_id']===''?'':($studentMap[$b['student_id']]['name']??$b['student_id']);return strnatcasecmp($nameA,$nameB);});
            $selected=(string)($_GET['ledger_student']??'');if($selected==='__class__')$selected='';
            if(isset($_GET['ledger_student'])&&isset($summaryById[$selected])){
                $selectedLedgerName=$selected===''?'Khoản chung cả lớp':($studentMap[$selected]['name']??'Học sinh đã chuyển lớp');
                $ledgerDetails=cmhome_rows($db,'SELECT id,entry_date,kind,amount,description,created_by FROM cmhome_ledger WHERE class_id=? AND school_year=? AND student_id=? AND entry_date BETWEEN ? AND ? ORDER BY entry_date DESC,id DESC',[$classId,$year,$selected,$month.'-01',date('Y-m-t',strtotime($month.'-01'))]);
            }
        }
        if($export!=='meals')foreach(cmhome_rows($db,'SELECT d.ledger_id FROM cmhome_ledger_done d JOIN cmhome_ledger l ON l.id=d.ledger_id AND l.class_id=d.class_id AND l.school_year=d.school_year WHERE d.class_id=? AND d.school_year=? AND l.entry_date BETWEEN ? AND ?',[$classId,$year,$month.'-01',date('Y-m-t',strtotime($month.'-01'))]) as $row)$ledgerDone[(int)$row['ledger_id']]=true;
    }
}
if($export!=='' && $class){require_once __DIR__.'/includes/classroom_home_export.php';cmhome_export_xlsx($export,$students,$mealData,$grams,$settings,$ledger,$class['name'],$year,$month,$mealDone,$ledgerDone);}
require defined('CDS_HOMEROOM_STANDALONE') ? dirname(__DIR__).'/includes/homeroom_header.php' : __DIR__.'/includes/header.php';
