<script>
function cmhFinanceKind(form){const kind=form.elements.kind.value;form.elements.payer.innerHTML=kind==='thu'?'<option value="students">Học sinh</option><option value="">— Để trống —</option><option value="teacher">GVCN</option><option value="fund">Quỹ lớp</option>':'<option value="">— Để trống —</option><option value="teacher">GVCN</option><option value="fund">Quỹ lớp</option><option value="scholarship">Ứng học bổng</option>';form.elements.receiver.innerHTML=kind==='thu'?'<option value="fund">Quỹ lớp</option><option value="">— Để trống —</option><option value="teacher">GVCN</option>':'<option value="">— Để trống —</option><option value="students">Học sinh</option><option value="class">Khoản chung cả lớp</option><option value="fund">Quỹ lớp</option>';const teacherLabel='GVCN · '+<?=json_encode($teacherName,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;form.querySelectorAll('option[value="teacher"]').forEach(option=>option.textContent=teacherLabel);cmhFinanceCount(form);}
function cmhFinanceCount(form){const invalid=form.elements.payer.value==='fund'&&form.elements.receiver.value==='fund';form.querySelector('button[type=submit],button:not([type])').disabled=invalid;const count=form.querySelectorAll('.cmh-ledger-list input:checked').length;const students=form.elements.payer.value==='students'||form.elements.payer.value==='scholarship'||form.elements.receiver.value==='students';form.querySelector('.cmh-finance-students').hidden=!students;form.querySelector('.cmh-finance-count').textContent=count+' em';const amount=Number(form.elements.amount.value)||0;const total=students&&form.elements.ledger_allocation.value==='each'?amount*count:amount;form.querySelector('.cmh-finance-preview').textContent=invalid?'Nguồn và nơi nhận không thể cùng là Quỹ lớp.':students?(count+' học sinh · tổng '+total.toLocaleString('vi-VN')+' đ'):'Khoản chung · '+total.toLocaleString('vi-VN')+' đ';}
function cmhFinanceCheck(form,checked){form.querySelectorAll('.cmh-ledger-list input').forEach(input=>input.checked=checked);cmhFinanceCount(form);}
document.querySelectorAll('.cmh-finance-form').forEach(cmhFinanceKind);
function cmhCompletionAll(type,checked){document.querySelectorAll('[data-completion-table="'+type+'"] tbody tr').forEach(row=>{const box=row.querySelector('input[name="completion_ids[]"]');if(box)box.checked=checked&&!row.hidden;});}
document.querySelectorAll('.cmh-page .table-responsive table').forEach(table=>{
 const body=table.tBodies[0],head=table.tHead;if(!body||!head||!body.rows.length)return;
 const wrapper=table.closest('.table-responsive');const tools=document.createElement('div');tools.className='cmh-table-tools';
 const search=document.createElement('input');search.type='search';search.className='form-control form-control-sm';search.placeholder='Lọc trong bảng…';search.setAttribute('aria-label','Lọc nội dung bảng');tools.append(search);
 let category=null;const labels=Array.from(head.rows[0].cells).map(th=>th.textContent.trim());const kindIndex=labels.indexOf('Loại');
 if(kindIndex>=0){category=document.createElement('select');category.className='form-select form-select-sm';category.innerHTML='<option value="">Tất cả loại</option><option value="thu">Thu</option><option value="chi">Chi</option>';category.setAttribute('aria-label','Lọc loại thu chi');tools.append(category);}
 const tally=document.createElement('span');tally.className='small text-muted ms-auto';tools.append(tally);wrapper.before(tools);
 const rows=Array.from(body.rows);const normalize=value=>value.toLocaleLowerCase('vi-VN');
 const apply=()=>{let count=0;const term=normalize(search.value.trim()),kind=category?category.value:'';rows.forEach(row=>{const ok=normalize(row.textContent).includes(term)&&(!kind||normalize(row.cells[kindIndex]?.textContent.trim()||'')===kind);row.hidden=!ok;if(ok)count++;});tally.textContent=count+'/'+rows.length+' dòng';};search.addEventListener('input',apply);if(category)category.addEventListener('change',apply);apply();
 Array.from(head.rows[0].cells).forEach((th,index)=>{const label=th.textContent.trim();if(!label)return;const button=document.createElement('button');button.type='button';button.className='cmh-sort-button';button.textContent=label;button.title='Sắp xếp theo '+label;th.textContent='';th.append(button);button.addEventListener('click',()=>{const asc=button.dataset.direction!=='asc';head.querySelectorAll('.cmh-sort-button').forEach(b=>b.removeAttribute('data-direction'));button.dataset.direction=asc?'asc':'desc';const values=rows.map(row=>row.cells[index]?.textContent.trim()||'');const numeric=values.every(v=>v===''||/^[-+]?\d[\d., ]*$/.test(v));rows.sort((a,b)=>{const left=a.cells[index]?.textContent.trim()||'',right=b.cells[index]?.textContent.trim()||'';let result=numeric?Number(left.replace(/\./g,'').replace(',','.'))-Number(right.replace(/\./g,'').replace(',','.')):left.localeCompare(right,'vi',{numeric:true,sensitivity:'base'});return asc?result:-result;});rows.forEach(row=>body.append(row));apply();});});
});
</script>
